<?php
declare(strict_types=1);

function adaExtraReviewedStateProfiles(): array
{
    $reviewed = [
        'AK' => ['Alaska', 'Alaska public-accommodation rules follow the ADA baseline for service animals in covered places. Use the federal ADA card as the primary access script and verify local or setting-specific rules when the question involves housing, schools, employment, or animals in training.', ['Federal ADA public-access rules apply in covered Alaska public accommodations.', 'The ADA task-work standard and two-question limit remain the safest baseline.', 'Emotional support, comfort, or companionship alone does not create ADA public-access rights.', 'Alaska-specific training-access language was not confirmed in this reviewed profile.'], 'Alaska service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Alaska fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Alaska State Commission for Human Rights / ADA baseline', 'https://humanrights.alaska.gov/'],
        'CT' => ['Connecticut', 'Connecticut state agency guidance follows the ADA baseline for service animals, defining service animals as dogs or miniature horses trained to perform disability-related work or tasks and limiting staff to the two ADA questions when the need is not obvious.', ['Connecticut public agency guidance welcomes service animals in public areas where members of the public may go.', 'Service animals are dogs or miniature horses individually trained for disability-related work or tasks.', 'Staff may ask only the two ADA-style questions when the need is not obvious.', 'Proof of disability, proof of certification, and training documentation are not required under the guidance.'], 'Connecticut service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Connecticut fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Connecticut DAS Service Animals Policy', 'https://portal.ct.gov/das/knowledge-base/articles/policies/service-animals'],
        'DC' => ['District of Columbia', 'D.C. law gives people with physical or mental disabilities equal access to public accommodations and conveyances with a service animal, without extra charge, and includes service animals in training with trainer or owner access under the Service Animal in Training Clarification Amendment Act.', ['People with physical or mental disabilities have full and equal access to public accommodations and conveyances.', 'They have the right to be accompanied by a service animal without extra charge, with liability for damage.', 'D.C. law recognizes service animals in training and allows the owner to serve as the accompanying trainer.', 'Service animals in training have age, training, accompaniment, and identifying-gear requirements under D.C. definitions.'], 'D.C. recognizes service animals in training and allows the owner of a service animal in training to serve as the trainer.', 'Housing may involve D.C. human-rights rules plus federal FHA reasonable-accommodation rules.', 'D.C. Code §§ 7-1002 and D.C. Law 23-208', 'https://code.dccouncil.gov/us/dc/council/code/sections/7-1002'],
        'DE' => ['Delaware', 'Delaware public-accommodation law generally aligns with the ADA service-animal framework after statutory updates, protecting task-trained service animals and excluding emotional-support-only animals from public-access service-animal status.', ['Delaware public accommodations must follow state and federal service-animal access rules.', 'The task-trained service-animal standard is the safest baseline for public access.', 'Emotional support animals do not qualify as service animals for public access unless trained for disability-related tasks.', 'Federal ADA two-question and no-documentation rules remain the baseline in ADA-covered places.'], 'Delaware service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Delaware fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Delaware Equal Accommodations Law / ADA baseline', 'https://delcode.delaware.gov/title6/c045/sc02/index.html'],
        'HI' => ['Hawaii', 'Hawaii public-accommodation access generally follows ADA service-animal rules for task-trained service animals in covered places. Hawaii also has state disability-rights and misrepresentation provisions, so use the federal ADA baseline and verify state or county context when needed.', ['Federal ADA public-access protections apply in Hawaii covered public accommodations.', 'The service animal must be trained to do disability-related work or tasks.', 'Emotional support, comfort, or companionship alone does not meet the ADA public-access standard.', 'Hawaii setting-specific rules may differ for housing, employment, schools, or quarantine/travel requirements.'], 'Hawaii service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Hawaii fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Hawaii Civil Rights Commission / ADA baseline', 'https://labor.hawaii.gov/hcrc/'],
        'MA' => ['Massachusetts', 'Massachusetts public resources explain that people with disabilities have the right to be accompanied by a service animal wherever the person is allowed to go, while noting that Massachusetts state service-animal law is narrower than the federal ADA in some respects and that federal ADA protections are broader.', ['Only dogs and, in rare cases, miniature horses can be service animals under the ADA baseline.', 'Massachusetts public guidance uses the familiar two-question framework.', 'Certification or identification is not required for assistance animals in Massachusetts, although ordinary municipal dog registration may still apply.', 'Massachusetts has separate assistance-animal housing guidance.'], 'Massachusetts has separate trainer-rights statutes for hearing-dog and service-dog trainers; verify training setting and trainer status before relying on it.', 'Massachusetts Office on Disability guidance covers assistance animals in housing and notes reasonable-accommodation processes.', 'Mass.gov Massachusetts law about service animals', 'https://www.mass.gov/info-details/massachusetts-law-about-service-animals'],
        'MD' => ['Maryland', 'Maryland law gives individuals with disabilities, parents of minor children with disabilities, and service animal trainers accompanied by animals being trained or raised as service animals the same rights to public places, transportation, public accommodations, and other places to which the general public is invited.', ['Maryland protects access for individuals with disabilities and parents of minor children with disabilities using service animals.', 'Service animal trainers accompanied by animals being trained or raised as service animals are also included.', 'The right extends to public places, common carriers, public conveyances, public accommodations, and places open to the public.', 'Maryland law also protects access even when the animal is not wearing an orange license tag or collar.'], 'Maryland expressly recognizes service animal trainers accompanied by animals being trained or raised as service animals.', 'Housing may involve Maryland disability-rights/fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Maryland Code, Human Services §§ 7-704 and 7-705', 'https://codes.findlaw.com/md/human-services/md-code-human-serv-sect-7-704/'],
        'ME' => ['Maine', 'Maine law distinguishes service animals for public accommodations from assistance animals in housing. Public accommodations focus on service animals, while housing may involve either service animals or assistance animals under Maine Human Rights Act guidance.', ['Maine defines service animal for public accommodations as a dog individually trained to do disability-related work or tasks.', 'Maine Human Rights Commission materials distinguish public-accommodation service animals from housing assistance animals.', 'Misrepresentation of a service animal or assistance animal can be a civil violation.', 'Maine has separate materials on assistance animals in housing.'], 'Maine references especially trained service dog trainers in some agency policy and Title 17 materials; verify current training-access details before relying on them.', 'Maine housing law recognizes assistance animals and service animals in reasonable-accommodation contexts.', 'Maine State Law Library — Service Animals', 'https://legislature.maine.gov/lawlibrary/what-is-maines-law-on-service-animals/9491'],
        'NH' => ['New Hampshire', 'New Hampshire law says a service animal may accompany its handler or trainer into any public facility, housing accommodation, or place of public accommodation to which the general public is invited, subject to generally applicable legal conditions.', ['A service animal may accompany its handler or trainer into covered public facilities and public accommodations.', 'Housing accommodations are included in the cited statute.', 'A service animal trainer has the same access rights and responsibilities while engaged in training.', 'The cited administrative definition uses a dog individually trained to do disability-related work or tasks.'], 'New Hampshire expressly recognizes service animal trainer access while engaged in the actual training process and activities.', 'Housing accommodations are included in the cited access statute, with federal FHA rules also relevant.', 'New Hampshire RSA 167-D:4 and 167-D:6', 'https://law.justia.com/codes/new-hampshire/2024/title-xii/chapter-167-d/section-167-d-4/'],
        'NJ' => ['New Jersey', 'New Jersey law and guidance protect service-animal access in public accommodations and include school-specific service-animal access for students with disabilities. Use the ADA baseline for general public access and verify school, housing, and training contexts separately.', ['Federal ADA public-access rules apply in New Jersey covered public accommodations.', 'New Jersey school law permits students with disabilities, including autism, access for service animals in school buildings, on school buses, and on school grounds.', 'School officials may ask whether the animal is required due to disability and what task or work it is trained to perform, unless obvious.', 'Schools may require vaccination and municipal-license documentation in the school context.'], 'New Jersey service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve New Jersey Law Against Discrimination and federal FHA reasonable-accommodation rules.', 'New Jersey Rev. Stat. § 18A:46-13.3 / NJ LAD baseline', 'https://law.justia.com/codes/new-jersey/title-18a/section-18a-46-13-3/'],
        'NY' => ['New York', 'New York public-accommodation law protects access for people with disabilities using service dogs, and federal ADA protections apply in covered public accommodations. New York also has separate state and city guidance for housing, employment, and public accommodations.', ['New York service-dog access is protected by state and federal public-accommodation law.', 'Federal ADA two-question and no-documentation rules remain the safest public-access baseline.', 'Emotional support, comfort, or companionship alone does not create ADA public-access rights.', 'New York City and state guidance may add local context in housing, employment, or public-facing services.'], 'New York service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve New York Human Rights Law, local rules such as NYC Human Rights Law, and federal FHA reasonable-accommodation rules.', 'New York State Human Rights Law / ADA baseline', 'https://dhr.ny.gov/'],
        'RI' => ['Rhode Island', 'Rhode Island law gives every person with a disability the right to be accompanied by a specially trained service animal in listed public places without extra charge, with liability for damage caused by the service animal.', ['Rhode Island protects service-animal access in listed public places and facilities.', 'No extra charge may be required for the service animal.', 'The handler is liable for damage done to people, premises, or facilities by the service animal.', 'Rhode Island public resources also explain the federal ADA service-animal baseline.'], 'Rhode Island service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Rhode Island human-rights/fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Rhode Island Gen. Laws § 40-9.1-2', 'https://law.justia.com/codes/rhode-island/title-40/chapter-40-9-1/section-40-9-1-2/'],
        'VT' => ['Vermont', 'Vermont public accommodations are covered by the federal ADA baseline for task-trained service animals. Use the ADA card as the primary public-access reference and verify Vermont-specific housing, employment, school, and training contexts separately.', ['Federal ADA public-access rules apply in covered Vermont public accommodations.', 'The ADA task-work definition and two-question limit are the safest baseline.', 'Emotional support, comfort, or companionship alone does not create ADA public-access rights.', 'Vermont-specific questions may arise in housing, employment, schools, or local government services.'], 'Vermont service-animal-in-training public-access rights were not confirmed in this reviewed profile; verify separately before relying on training access.', 'Housing may involve Vermont fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Vermont Human Rights Commission / ADA baseline', 'https://hrc.vermont.gov/'],
        'IA' => ['Iowa', 'Iowa law gives people with disabilities full and equal access to public places and accommodations with service dogs and assistive animals, and separately gives trainers access while training service dogs and assistive animals.', ['Iowa protects access to public facilities and accommodations for people with disabilities using service dogs or assistive animals.', 'Trainers of service dogs and assistive animals are protected while training in listed public places.', 'Extra charges are barred, but the person or trainer may be liable for damage.', 'Federal ADA rules still apply in ADA-covered public accommodations.'], 'Iowa recognizes trainer access while training service dogs and assistive animals.', 'Housing may involve Iowa civil-rights rules plus federal FHA reasonable-accommodation rules.', 'Iowa Code Chapter 216C', 'https://www.legis.iowa.gov/docs/code/216C.pdf'],
        'IL' => ['Illinois', 'Illinois law protects public-access rights for people using guide, hearing, or support dogs and recognizes access for trainers affiliated with recognized training programs. Illinois also has separate housing and misrepresentation provisions.', ['Illinois protects access to public accommodations and other covered places for people with disabilities accompanied by trained service dogs.', 'Illinois recognizes guide, hearing, and support dogs in state law.', 'Trainers affiliated with recognized training programs may have access while training in covered places.', 'Extra charges are barred, but damage liability may apply.'], 'Illinois training access is tied to recognized training programs and trainer status in the reviewed state-law materials.', 'Housing may involve Illinois assistance-animal rules plus federal FHA reasonable-accommodation rules.', 'Illinois White Cane Law / Service Animal Access Act materials', 'https://www.ilga.gov/legislation/ilcs/ilcs3.asp?ActID=2104&ChapterID=59'],
        'IN' => ['Indiana', 'Indiana law protects access for people with disabilities accompanied by guide dogs or service animals and recognizes training access for service animals in training.', ['Indiana protects access to public accommodations and public facilities for people with disabilities using service animals.', 'The state uses guide dog and service animal language across related provisions.', 'Service-animal-in-training access is recognized in state law.', 'Extra charges may be barred, while damage liability may apply.'], 'Indiana recognizes service-animal-in-training access; verify trainer and setting-specific requirements before relying on it.', 'Housing may involve Indiana civil-rights/fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Indiana Code Title 16 and Title 22 service animal provisions', 'https://iga.in.gov/laws/2024/ic/titles/016#16-32-3'],
        'MI' => ['Michigan', 'Michigan law protects access for people with disabilities using service animals and recognizes service animals in training in public accommodations when handled by certain trainers. Michigan also addresses voluntary service-animal identification.', ['Michigan public-accommodation law protects people with disabilities using service animals.', 'Service animals in training may be covered when handled by a trainer, raiser, or representative of a service-animal training organization.', 'Michigan has voluntary service-animal identification provisions, but ADA public-access rights do not depend on registration.', 'Misrepresentation and interference provisions may apply under Michigan law.'], 'Michigan training access is tied to trainer/raiser/organization-related status in the reviewed materials.', 'Housing may involve Michigan fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Michigan service animal laws / MDCR service animal guidance', 'https://www.michigan.gov/mdcr/divisions/ada-compliance/service-animals'],
        'MN' => ['Minnesota', 'Minnesota law protects access for people with disabilities accompanied by service animals and recognizes access for trainers of service animals in training in public places.', ['Minnesota protects access for people with disabilities accompanied by service animals.', 'Service animals in training and trainers are recognized in state law.', 'Public accommodations may not require extra charges because of the service animal.', 'Handlers may remain responsible for control and damage.'], 'Minnesota recognizes trainers and service animals in training; confirm setting-specific details before relying on training access.', 'Housing may involve Minnesota human-rights/fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Minnesota Statutes Chapter 363A service animal provisions', 'https://www.revisor.mn.gov/statutes/cite/363A.19'],
        'ND' => ['North Dakota', 'North Dakota law protects access for individuals with disabilities accompanied by service animals and recognizes service animals in training in public accommodations when accompanied by a trainer.', ['North Dakota protects access to public accommodations for people with disabilities using service animals.', 'Service animals in training may be admitted when accompanied by a trainer.', 'A trainer or handler can be liable for damage caused by the animal.', 'Federal ADA two-question and documentation limits remain the baseline in ADA-covered places.'], 'North Dakota recognizes service-animal-in-training access when accompanied by a trainer, subject to control and setting-specific rules.', 'Housing may involve North Dakota fair-housing rules plus federal FHA reasonable-accommodation rules.', 'North Dakota Century Code Chapter 25-13', 'https://ndlegis.gov/cencode/t25c13.pdf'],
        'OH' => ['Ohio', 'Ohio law protects people with disabilities accompanied by assistance dogs in public accommodations and housing accommodations, and also recognizes trainers of assistance dogs in training.', ['Ohio protects access for people with disabilities using trained assistance dogs.', 'Ohio has public-accommodation and housing-accommodation language.', 'Trainers of assistance dogs are recognized in state law.', 'Extra charges are barred, but damage liability may apply.'], 'Ohio recognizes assistance-dog trainers and assistance dogs in training; verify exact trainer and setting requirements.', 'Ohio housing access is addressed in state law, with federal FHA rules also relevant.', 'Ohio Revised Code § 955.43', 'https://codes.ohio.gov/ohio-revised-code/section-955.43'],
        'PA' => ['Pennsylvania', 'Pennsylvania law protects access for people using guide, signal, or service dogs and recognizes access for handlers or trainers of service dogs in training under state law.', ['Pennsylvania protects access for people with disabilities accompanied by guide, signal, or service dogs.', 'Service dogs in training and handlers/trainers may be recognized in state access law.', 'Extra charges are generally barred, while damage liability may apply.', 'Federal ADA limits on documentation and inquiry still apply in ADA-covered public accommodations.'], 'Pennsylvania recognizes service-dog-in-training access in reviewed state-law materials; verify trainer and identification details by setting.', 'Housing may involve Pennsylvania human-relations/fair-housing rules plus federal FHA reasonable-accommodation rules.', 'Pennsylvania Human Relations Act / service animal access resources', 'https://www.pa.gov/agencies/phrc/programs-and-services/disability-rights.html'],
        'WI' => ['Wisconsin', 'Wisconsin law protects access for people with disabilities accompanied by service animals and recognizes service animals in training accompanied by trainers in public places and accommodations.', ['Wisconsin protects access to public places and accommodations for people with disabilities using service animals.', 'Service animals in training accompanied by trainers are recognized under state law.', 'Extra charges are barred, though handlers/trainers may be liable for damage.', 'Federal ADA rules remain the baseline for ADA-covered public accommodations.'], 'Wisconsin recognizes service animals in training when accompanied by trainers in covered public places.', 'Housing may involve Wisconsin open-housing rules plus federal FHA reasonable-accommodation rules.', 'Wisconsin Statutes § 106.52', 'https://docs.legis.wisconsin.gov/statutes/statutes/106/52'],
    ];

    $profiles = [];
    foreach ($reviewed as $code => $p) {
        $profiles[$code] = adaReviewedStateProfile($code, $p[0], $p[1], $p[2], $p[3], $p[4], $p[5], $p[6]);
    }
    return $profiles;
}
